HEALTH=""
for i in $(seq 1 60); do
  HEALTH="$(curl -fsS --connect-timeout 2 --max-time 4 http://127.0.0.1:${HOST_PORT}/api/health 2>/dev/null || true)"
  if [[ -n "$HEALTH" ]] && printf '%s' "$HEALTH" | python3 -c 'import sys,json; h=json.load(sys.stdin); raise SystemExit(0 if h.get("ok") is True and h.get("version")=="NOVA-2.4.22" else 1)' 2>/dev/null; then break; fi
  sleep 2
done
[[ -n "$HEALTH" ]] || { sudo docker logs --tail 250 "$CONTAINER" || true; echo "health 응답 실패" >&2; false; }
printf '%s' "$HEALTH" > "$TMP/health.json"
python3 - "$TMP/health.json" <<'PYHEALTH'
import json,sys
h=json.load(open(sys.argv[1])); assert h.get('ok') is True; assert h.get('version')=='NOVA-2.4.22'
ct=h.get('ws_contract') or {}; assert (ct.get('trade_type'),ct.get('program_type'),ct.get('orderbook_type'))==('0B','0u','0D'),ct
assert ct.get('source')=='OFFICIAL_FIXED_CONTRACT',ct
ep=h.get('entry_policy') or {}
assert '0B/0u/0D' in str(ep.get('ws_contract_probe') or ''),ep.get('ws_contract_probe')
assert '0u' in str(ep.get('program_realtime') or '') and 'ka90003' in str(ep.get('program_realtime') or ''),ep.get('program_realtime')
assert ep.get('venue_truth_policy')=='OFFICIAL_ITEM_SUFFIX_PRIMARY + FID9081_CROSSCHECK; CONFLICT=>UNKNOWN_FAIL_CLOSED'
assert ep.get('quota_enforced') is False and ep.get('max_daily')==2
w=h.get('ws') or {}
# During startup the targets may not yet be ACKed, but the running engine must expose the budget once scheduling starts.
assert (h.get('entry_policy') or {}).get('ws_registry')=='SESSION_AWARE_HARD_CAP_SERIAL_DIFF_ACTIVE_VENUE_ONLY'
rs=h.get('relative_strength_shadow') or {}; assert rs.get('auto_apply') is False and rs.get('buy_effect') is False
rsl=h.get('rs_leader_table') or {}; assert rsl.get('version')=='RS_LEADER_TABLE_V2' and int(rsl.get('kiwoom_extra_requests') or 0)==0 and rsl.get('buy_effect') is False
print('HEALTH_STRUCTURE=PASS contract=0B/0u/0D')
PYHEALTH

# R16 liveness soak: post-close review tasks become eligible within seconds after startup.
# Require the SAME host->container path used by the UI to remain responsive repeatedly.
echo 'R17_LIVENESS_SOAK=START probes=8 interval=2s max_time=3s retries=3'
R16_LAT_FILE="$TMP/r16_health_latency.txt"; : > "$R16_LAT_FILE"
for i in $(seq 1 8); do
  probe_file="$TMP/r16_health_$i.json"
  T=""
  for attempt in 1 2 3; do
    rm -f "$probe_file"
    if T="$(curl -fsS --connect-timeout 1 --max-time 3 -o "$probe_file" -w '%{time_total}' "http://127.0.0.1:${HOST_PORT}/api/health" 2>/dev/null)" && [[ -s "$probe_file" ]]; then
      break
    fi
    T=""
    sleep 1
  done
  [[ -n "$T" && -s "$probe_file" ]] || { echo "R17_LIVENESS_SOAK=FAIL probe=$i no_valid_body_after_3_attempts" >&2; exit 1; }
  python3 - "$probe_file" "$T" <<'PYR16PROBE'
import json,sys
h=json.load(open(sys.argv[1])); t=float(sys.argv[2])
assert h.get('ok') is True and h.get('version')=='NOVA-2.4.22'
assert t < 3.0, t
print(f'R17_HEALTH_PROBE=PASS time={t:.3f}s')
PYR16PROBE
  printf '%s\n' "$T" >> "$R16_LAT_FILE"
  sleep 2
done
python3 - "$R16_LAT_FILE" <<'PYR16LAT'
import sys,statistics
x=[float(v.strip()) for v in open(sys.argv[1]) if v.strip()]
x.sort(); p95=x[min(len(x)-1,max(0,int(len(x)*.95)-1))]
assert len(x)==8 and max(x)<3.0
print(f'R17_LIVENESS_SOAK=PASS probes={len(x)} max={max(x):.3f}s median={statistics.median(x):.3f}s p95={p95:.3f}s')
PYR16LAT

api_get() {
  local endpoint="$1" timeout="${2:-12}" tries="${3:-4}" body="" i
  for i in $(seq 1 "$tries"); do
    body="$(curl -fsS --connect-timeout 2 --max-time "$timeout" "http://127.0.0.1:${HOST_PORT}${endpoint}" 2>/dev/null || true)"
    if [[ -n "$body" ]] && printf '%s' "$body" | python3 -c 'import sys,json; json.load(sys.stdin)' >/dev/null 2>&1; then
      printf '%s' "$body"
      return 0
    fi
    sleep 2
  done
  return 1
}

# Core APIs are retried because the new container may still be warming caches.
for endpoint in /api/ws-contract /api/rs-leaders /api/nxt-signal-table /api/buy-signals /api/nxt-alerts /api/exit-dna /api/evidence; do
  echo "CHECK_API=$endpoint"
  api_get "$endpoint" 12 5 >/dev/null || { echo "CORE_API_CHECK_FAILED=$endpoint" >&2; false; }
done
# Backtest status can legitimately be slow during startup and is not required for LIVE BUY operation.
echo "CHECK_API=/api/backtest/status (nonfatal)"
api_get /api/backtest/status 15 2 >/dev/null || echo "BACKTEST_STATUS=WARMUP_TIMEOUT_NONFATAL"

api_get /api/ws-contract 12 5 | python3 -c 'import sys,json;j=json.load(sys.stdin); c=j.get("contract") or {}; assert j.get("version")=="NOVA-2.4.22"; assert (c.get("trade_type"),c.get("program_type"),c.get("orderbook_type"))==("0B","0u","0D"); print("WS_CONTRACT_API=PASS",c.get("trade_type"),c.get("program_type"),c.get("orderbook_type"))'
api_get /api/rs-leaders 12 5 | python3 -c 'import sys,json;j=json.load(sys.stdin); assert j.get("version")=="NOVA-2.4.22"; assert int(j.get("kiwoom_extra_requests_per_poll") or 0)==0; print("RS_LEADERS_API=PASS rows=",j.get("count"),"readiness=",(j.get("readiness") or {}).get("status"))'
api_get /api/nxt-signal-table 12 5 | python3 -c 'import sys,json;j=json.load(sys.stdin); assert j.get("version")=="NOVA-2.4.22"; assert int(j.get("display_limit") or 0)==20; print("NXT_QUIET_TABLE=PASS displayed=",j.get("count"),"raw=",j.get("raw_count"))'
BUY_JSON="$(api_get /api/buy-signals 15 5)" || { echo "PRIMARY_BUY_API_CHECK_FAILED" >&2; false; }
printf '%s' "$BUY_JSON" | python3 -c 'import sys,json;j=json.load(sys.stdin); assert j.get("version")=="NOVA-2.4.22"; assert isinstance(j.get("near_miss_rows"),list); print("BUY_DIAGNOSTIC=PASS buy=",j.get("count"),"near_miss=",len(j.get("near_miss_rows") or []))'
printf '%s' "$BUY_JSON" | python3 -c 'import sys,json;j=json.load(sys.stdin); assert isinstance(j.get("prebuy_rows"),list); assert j.get("prebuy_policy","").startswith("PRIMARY_ADVISORY_PRE_SURGE"); assert len(j.get("prebuy_rows") or [])<=10; print("PRIMARY_PREBUY_API=PASS rows=",len(j.get("prebuy_rows") or []))'
api_get /api/nova 15 5 | python3 -c 'import sys,json;j=json.load(sys.stdin); h=j.get("health") or {}; assert h.get("candidate_count_policy")=="STABLE_LIVE_BOARD_WS_ADMISSION_HYSTERESIS"; assert int(h.get("live_board_count") or 0)<=10; bad=[r for r in (j.get("rows") or []) if r.get("evidence",{}).get("session_vwap_gap") is not None and abs(float(r["evidence"]["session_vwap_gap"]))>60]; assert not bad,bad[:2]; print("LIVE_BOARD_VWAP_API=PASS fresh=",h.get("candidate_count"),"board=",h.get("live_board_count"))'

LIVE_WS_STATUS="DEFERRED"
LIVE_WS_LAST_LINE="session_inactive"
SESSION_ACTIVE="$(api_get /api/health 12 5 | python3 -c 'import sys,json; h=json.load(sys.stdin); n=h.get("nxt_after") or {}; print("1" if n.get("regular_active") or n.get("premarket_active") or n.get("after_active") else "0")')"
if [[ "$SESSION_ACTIVE" == "1" ]]; then
  echo "LIVE_WS_GATE=OBSERVE max=150s container_start=$LIVE_GATE_START_EPOCH nonfatal=1"
  LIVE_OK=0
  LIVE_WS_STATUS="PENDING"
  for i in $(seq 1 50); do
    J="$(curl -fsS --connect-timeout 2 --max-time 4 http://127.0.0.1:${HOST_PORT}/api/health 2>/dev/null || true)"
    if [[ -n "$J" ]]; then
      printf '%s' "$J" > "$TMP/live.json"
      LINE="$(python3 - "$TMP/live.json" "$LIVE_GATE_START_EPOCH" <<'PYLIVE'
import sys,json
h=json.load(open(sys.argv[1])); start=float(sys.argv[2]); w=h.get('ws') or {}; f=h.get('feed') or {}; ct=h.get('ws_contract') or {}
connected=bool(w.get('connected')); tr=int(w.get('trade_registered') or 0); lt=float(w.get('last_trade_at') or 0); ack=int(w.get('ack') or 0)
prog=int(w.get('program_registered') or 0); ob=int(w.get('orderbook_registered') or 0)
pt=int(w.get('registry_target_program') or 0); ot=int(w.get('registry_target_orderbook') or 0)
contract=(ct.get('trade_type'),ct.get('program_type'),ct.get('orderbook_type'))
aux_ok=(pt==0 or prog>0) and (ot==0 or ob>0) and not w.get('program_reg_error') and not w.get('orderbook_reg_error')
ok=connected and tr>0 and lt>=start-5 and contract==('0B','0u','0D') and f.get('state')!='DISCONNECTED' and aux_ok
print(('PASS' if ok else 'WAIT')+f" connected={connected} trade_reg={tr} krx={int(w.get('krx_registered') or 0)} nxt={int(w.get('nxt_registered') or 0)} program={prog}/{pt} orderbook={ob}/{ot} ack={ack} feed={f.get('state')} last_trade={lt:.3f} program_error={str(w.get('program_reg_error') or '')[:60]} orderbook_error={str(w.get('orderbook_reg_error') or '')[:60]} last_error={str(w.get('last_error') or '')[:80]}")
PYLIVE
)"
      LIVE_WS_LAST_LINE="$LINE"
      echo "LIVE_WS[$i] $LINE"
      if [[ "$LINE" == PASS* ]]; then LIVE_OK=1; LIVE_WS_STATUS="PASS"; break; fi
    fi
    sleep 3
  done
  if [[ $LIVE_OK -ne 1 ]]; then
    LIVE_WS_STATUS="PENDING"
    echo "LIVE_WS_GATE=PENDING — core deploy remains active; live data verification did not complete within 150s" >&2
    {
      echo "status=PENDING"
      echo "version=NOVA-$VERSION"
      echo "observed_at=$(date -Is)"
      echo "last_line=$LIVE_WS_LAST_LINE"
      echo "--- health ---"
      curl -fsS --max-time 5 http://127.0.0.1:${HOST_PORT}/api/health 2>&1 || true
      echo
      echo "--- logs tail 300 ---"
      sudo docker logs --tail 300 "$CONTAINER" 2>&1 || true
    } > "$APP_DIR/deployments/NOVA-${VERSION}-${STAMP}-LIVE-WS-PENDING.diag" 2>&1 || true
  fi
else
  echo "LIVE_WS_GATE=DEFERRED session_inactive; contract/selfcheck only"
fi

say "7/7 완료 — CORE DEPLOY PASS + LIVE WS STATUS"
if [[ $OLD_RENAMED -eq 1 ]]; then sudo docker rm -f "$BACKUP" >/dev/null 2>&1 || true; OLD_RENAMED=0; fi
SUCCESS=1
trap - ERR
RECEIPT="$APP_DIR/deployments/2.4.22-${STAMP}.receipt"
{
  echo "version=NOVA-2.4.22"
  echo "image=$IMAGE"
  echo "zip_sha256=$EXPECTED_ZIP_SHA256"
  echo "contract=0B/0u/0D"
  echo "deploy_core_gate=PASS"
  echo "live_ws_gate=$LIVE_WS_STATUS"
  echo "live_ws_last=$LIVE_WS_LAST_LINE"
  echo "installed_at=$(date -Is)"
  sudo docker inspect "$CONTAINER" --format 'container_status={{.State.Status}} image={{.Config.Image}}'
} > "$RECEIPT"
sudo docker image prune -f >/dev/null 2>&1 || true

echo "FINAL_HEALTH=PASS version=NOVA-2.4.22 installer_rev=$INSTALLER_REV live_ws_gate=$LIVE_WS_STATUS"
echo "OFFICIAL_WS_CONTRACT=0B/0u/0D"
echo "WS_REG_GUARD=SESSION_AWARE budget=160 trade_per_venue<=40 program<=15 orderbook<=10"
echo "LIVE_CANDIDATE_UI=PRIMARY_BUY_STABLE + WS_RECONNECT_HOLD_NONACTIONABLE"
echo "PROGRAM_REST_FALLBACK=ka90003"
echo "IMAGE=$IMAGE"
echo "CONTAINER=$CONTAINER"
echo "STATUS=$(sudo docker inspect "$CONTAINER" --format '{{.State.Status}}')"
echo "DATA_DIR=$APP_DIR/data"
echo "PUBLIC_URL=https://3-38-25-20.nip.io"
echo "DEPLOY_RECEIPT=$RECEIPT"
curl -fsS http://127.0.0.1:${HOST_PORT}/api/health | python3 -c 'import sys,json;h=json.load(sys.stdin);w=h.get("ws") or {};f=h.get("feed") or {};c=h.get("ws_contract") or {};print("feed=",f.get("state"));print("connected=",w.get("connected"),"trade_registered=",w.get("trade_registered"),"program_registered=",w.get("program_registered"),"orderbook_registered=",w.get("orderbook_registered"));print("contract=",c.get("trade_type"),c.get("program_type"),c.get("orderbook_type"),c.get("source"));print("last_trade_at=",w.get("last_trade_at"),"last_error=",w.get("last_error"))'
